  "contradictory_card_ids": ["C204","C206","C208","C284","C278","C294","C257","C274","C254"],
  "prediction_basis_card_ids": ["C01","C03","C06","C09","C15","C17","C27","C30","C33","C172","C219","C204","C206","C208","C284","C278","C257","C274","C254"],
  "claims": [
    {
      "claim": "All L1 gold contexts report absolute oral F values at or above 32% (silodosin 32%, aprepitant 59-67%, basmisanil ~75%, bepotastine >80%, lemborexant >=87%, encainide 76-78%, alizapride 72.5-89.7%, setipiprant >=50%); no L1 gold context supports F <20%.",
      "card_ids": ["C01","C03","C06","C09","C15","C17","C27","C30","C33"]
    },
    {
      "claim": "The query shares the 6-fluoro-1,2-benzisoxazol-3-yl piperidine core with risperidone (M01); L4/L5 records classify risperidone as high adsorptive permeability (Papp >10 ×10^-6 cm/s), supporting the intestinal absorption component for this scaffold.",
      "card_ids": ["C172","C219"]
    },
    {
      "claim": "L5 shows risperidone is a P-gp substrate with inhibitable efflux, and L6 shows moderate hepatic intrinsic clearance for the closest analogs (risperidone HLM CLint 40 µL/min/mg; CYP3A4 CLint 9 L/h; paliperidone CYP2D6/CYP3A4 metabolism); these are mechanistic presystemic-loss factors, but no record provides a direct F <20% for the query or a close analog.",
      "card_ids": ["C204","C206","C208","C284","C278","C257","C274","C254"]
    },
    {
      "claim": "No affirmative threshold-relevant evidence supports F <20%; the high prediction is retained, with confidence moderated by the absence of query-specific F and the presence of P-gp efflux and hepatic metabolism in the closest analog.",
      "card_ids": ["C284","C278","C204","C206","C208","C219"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "weakened",
      "card_ids": ["C284","C278","C294","C257","C274","C254"]
    }
  ],
  "evidence_gaps": [
    "No direct iloperidone-specific absolute F measurement is present; the decision relies on transferred contexts and structural analogy to risperidone/paliperidone.",
    "No query-specific hepatic clearance or metabolic-stability experiment is available; L6 records are for risperidone, paliperidone, and other compounds.",
    "The magnitude of first-pass hepatic extraction for the query is not quantified; HLM CLint values are assay-specific and not threshold-relevant.",
    "No query-specific gut-wall efflux or intestinal metabolism experiment is available; L5 records are for risperidone and other compounds.",
    "Food effect, formulation, and dose-response for the query are not provided.",
    "No affirmative sub-20% evidence exists, but absence of direct query F leaves residual uncertainty."
  ],
  "decision_summary": "L6 adds mechanistic hepatic clearance/metabolic-stability evidence for the closest analogs risperidone and paliperidone (moderate HLM CLint, CYP3A4/CYP2D6 metabolism), a directionally negative presystemic-loss factor, but no direct F <20% outcome and no query-specific measurement; all direct gold F values are >=32% and the shared benzisoxazole-piperidine scaffold shows high absorptive permeability, so the high prediction is retained with moderate confidence."
}

